using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    // CalculateTotal – DataRow (inline constant data)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00, 5, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – DynamicData (complex/decimal-precise scenarios)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> CalculateTotalTestData
    {
        get
        {
            yield return new object[] { 19.99m, 4, 0.0725m, 85.7572m };
            yield return new object[] { 1000m, 1, 0.0m, 1000m };
            yield return new object[] { 0.01m, 100, 0.05m, 1.05m };
            yield return new object[] { 49.95m, 10, 1.0m, 999.00m }; // max tax rate (100%)
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalTestData))]
    public void CalculateTotal_WithDynamicData_ReturnsExpectedTotal(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – invalid inputs throw
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0, 1, 0.1, DisplayName = "Negative unit price")]
    [DataRow(10.0, -1, 0.1, DisplayName = "Negative quantity")]
    [DataRow(10.0, 1, -0.1, DisplayName = "Negative tax rate")]
    [DataRow(10.0, 1, 1.5, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – DataRow
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% off")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% off (free)")]
    [DataRow(49.99, 25.0, 37.4925, DisplayName = "25% off fractional price")]
    public void ApplyDiscount_WithValidInputs_ReturnsDiscountedPrice(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – DynamicData from method (alternative source)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> InvalidDiscountData()
    {
        yield return new object[] { 100m, -1m };
        yield return new object[] { 100m, 101m };
        yield return new object[] { 50m, -0.01m };
        yield return new object[] { 200m, 150m };
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData), DynamicDataSourceType.Method)]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }
}

